{% set url_token = frappe.form_dict.get("dr_token") or "" %}
{% set saved_token = doc.custom_dr_print_token or "" %}
{% set already_printed = doc.custom_dr_printed|int %}
{% set print_count = doc.custom_dr_print_count|int %}

{% if doc.status != "To Bill" %}

<div style="text-align: center; margin-top: 100px; font-size: 18px; font-weight: bold; color: #b00020;">
	Printing is not allowed.
	<br><br>
	This Delivery Note status is: {{ doc.status }}
	<br>
	Printing is only allowed when status is To Bill.
</div>

{% elif not url_token or url_token != saved_token %}

<div style="text-align: center; margin-top: 100px; font-size: 18px; font-weight: bold; color: #b00020;">
	Print authorization is invalid.
	<br><br>
	Please use the Print DR button from the Delivery Note form.
</div>

{% elif already_printed != 1 or print_count <= 0 %}

<div style="text-align: center; margin-top: 100px; font-size: 18px; font-weight: bold; color: #b00020;">
	This Delivery Note is not yet marked as printed.
	<br><br>
	Please use the Print DR button from the Delivery Note form.
</div>

{% else %}

<script>
	window.addEventListener("load", function() {
		setTimeout(function() {
			window.print();
		}, 500);

		window.onafterprint = function() {
			document.body.innerHTML =
				'<div style="text-align:center; margin-top:100px; font-size:18px; font-weight:bold;">' +
				'DR printing has been completed and this page is now locked.' +
				'</div>';

			setTimeout(function() {
				window.close();
			}, 1000);
		};
	});
</script>

