                <div class="sign-name">{{ checked_by }}</div>
                <div class="sign-position">Accounting Associate Team Lead</div>
            </td>
            <td>
                <div class="sign-name">{{ noted_by }}</div>
                <div class="sign-position">Accounting Manager</div>
            </td>
            <td>
                <div class="sign-name">{{ approved_by }}</div>
                <div class="sign-position">CEO</div>
            </td>
            <td>
                <div class="sign-name">{{ received_by }}</div>
                <div class="sign-position">Signature over printed name/Date</div>
            </td>
        </tr>
    </table>

</div>

