{# ==========================================================
   ACKNOWLEDGEMENT RECEIPT
   SOURCE: PAYMENT ENTRY
========================================================== #}


{# ==========================================================
   BASIC PAYMENT INFORMATION
========================================================== #}

{% set company_name = doc.company or "" %}
{% set customer_name = doc.party_name or doc.party or "" %}
{% set receipt_date = doc.posting_date or "" %}


{% set currency =
    doc.paid_from_account_currency
    or doc.paid_to_account_currency
    or "PHP"
%}


{% set receipt_amount =
    doc.paid_amount
    or doc.received_amount
    or 0
%}


{# ==========================================================
   PHYSICAL AR NUMBER
========================================================== #}

{% set ar_no = doc.custom_ar_no or "" %}


{# ==========================================================
   CUSTOMER INFORMATION
========================================================== #}

{% set customer_tax_id = "" %}
{% set customer_industry = "" %}
{% set party_bank_account = "" %}
{% set primary_address = "" %}


{% if doc.party_type == "Customer" and doc.party %}


    {% set customer_tax_id =
        frappe.db.get_value(
            "Customer",
            doc.party,
            "tax_id"
        ) or ""
    %}


    {% set customer_industry =
        frappe.db.get_value(
            "Customer",
            doc.party,
            "industry"
        ) or ""
    %}


    {% set party_bank_account =
        frappe.db.get_value(
            "Customer",
            doc.party,
            "party_bank_account"
        ) or ""
    %}


    {% set primary_address =
        frappe.db.get_value(
            "Customer",
            doc.party,
            "customer_primary_address"
        ) or ""
    %}


{% endif %}


{# ==========================================================
   CUSTOMER ADDRESS
========================================================== #}

{% set address_line1 = "" %}
{% set address_line2 = "" %}
{% set address_city = "" %}
{% set address_state = "" %}
{% set address_pincode = "" %}
{% set customer_address = "" %}


{% if primary_address %}


    {% set address_line1 =
        frappe.db.get_value(
            "Address",
            primary_address,
            "address_line1"
        ) or ""
    %}


    {% set address_line2 =
        frappe.db.get_value(
            "Address",
            primary_address,
            "address_line2"
        ) or ""
    %}


    {% set address_city =
        frappe.db.get_value(
            "Address",
            primary_address,
            "city"
        ) or ""
    %}


    {% set address_state =
        frappe.db.get_value(
            "Address",
            primary_address,
            "state"
        ) or ""
    %}


    {% set address_pincode =
        frappe.db.get_value(
            "Address",
            primary_address,
            "pincode"
        ) or ""
    %}


    {% set addr = namespace(parts=[]) %}


    {% if address_line1 %}
        {% set addr.parts =
            addr.parts + [address_line1]
        %}
    {% endif %}


    {% if address_line2 %}
        {% set addr.parts =
            addr.parts + [address_line2]
        %}
    {% endif %}


    {% if address_city %}
        {% set addr.parts =
            addr.parts + [address_city]
        %}
    {% endif %}


    {% if address_state %}
        {% set addr.parts =
            addr.parts + [address_state]
        %}
    {% endif %}


    {% if address_pincode %}
        {% set addr.parts =
            addr.parts + [address_pincode]
        %}
    {% endif %}


    {% set customer_address =
        addr.parts|join(", ")
    %}


{% endif %}


{# ==========================================================
   CUSTOMER BANK ACCOUNT
========================================================== #}

{% set bank_name = "" %}
{% set bank_branch = "" %}


{% if party_bank_account %}


    {% set bank_name =
        frappe.db.get_value(
            "Bank Account",
            party_bank_account,
            "bank"
        ) or ""
    %}


    {% set bank_branch =
        frappe.db.get_value(
            "Bank Account",
            party_bank_account,
            "branch_code"
        ) or ""
    %}


{% endif %}


{# ==========================================================
   CHECK INFORMATION
========================================================== #}

{% set check_no = doc.reference_no or "" %}
{% set check_date = doc.reference_date or "" %}


{# ==========================================================
   MODE OF PAYMENT
========================================================== #}

{% set payment_mode =
    (doc.mode_of_payment or "")|lower
%}


{% set is_cash =
    "cash" in payment_mode
%}


{% set is_check =
    "check" in payment_mode
    or "cheque" in payment_mode
%}


{# ==========================================================
   SALES INVOICE REFERENCES
========================================================== #}

{% set refs = namespace(
    invoices=[],
    invoice_numbers=[],
    total_allocated=0
) %}


{% for row in doc.references or [] %}


    {% if row.reference_doctype == "Sales Invoice" %}


        {% set refs.invoice_numbers =
            refs.invoice_numbers
            + [row.reference_name]
        %}


        {% set refs.total_allocated =
            refs.total_allocated
            + (row.allocated_amount or 0)
        %}


        {% set refs.invoices =
            refs.invoices
            + [{
                "name": row.reference_name,
                "allocated": row.allocated_amount or 0,
                "outstanding": row.outstanding_amount or 0
            }]
        %}


    {% endif %}


{% endfor %}


{# ==========================================================
   PAYMENT DESCRIPTION
========================================================== #}

{% set payment_description = "Payment" %}


{% if refs.invoices|length == 1 %}


    {% set inv = refs.invoices[0] %}


    {% if inv.outstanding > 0
          and inv.allocated >= inv.outstanding %}


        {% set payment_description =
            "FULL PAYMENT for Sales Invoice "
            ~ inv.name
        %}


    {% else %}


        {% set payment_description =
            "PARTIAL PAYMENT for Sales Invoice "
            ~ inv.name
        %}


    {% endif %}


{% elif refs.invoices|length > 1 %}


    {% set payment_description =
        "Payment for Sales Invoices "
        ~ refs.invoice_numbers|join(", ")
    %}


{% endif %}


{# ==========================================================
   AMOUNT IN WORDS
========================================================== #}

{% set amount_words =
    frappe.utils.money_in_words(
        receipt_amount,
        currency
    )
%}



<style>

    /* ======================================================
       PAPER
       210mm x 105mm
    ====================================================== */

    @page {
        size: 210mm 105mm;
        margin: 0;
    }


    html,
    body {
        margin: 0 !important;
        padding: 0 !important;
    }


    .print-format {
        width: 210mm !important;
        min-height: 105mm !important;

        margin: 0 !important;
        padding: 0 !important;

        font-family: Arial, Helvetica, sans-serif;

        font-size: 11px;

        line-height: 1.20;

        color: #111;

        box-sizing: border-box;
    }


    .ar-container {

        width: 210mm;
        height: 105mm;

        margin: 0;

        /*
            Physical safe printing area

            TOP    = 6mm
            RIGHT  = 8mm
            BOTTOM = 5mm
            LEFT   = 8mm
        */

        padding:
            6mm
            8mm
            5mm
            8mm;

        box-sizing: border-box;

        overflow: hidden;
    }



    /* ======================================================
       HEADER
    ====================================================== */

    .ar-header {

        position: relative;

        text-align: center;

        min-height: 43px;

        margin: 0 0 3px 0;
    }


    .company-name {

        font-size: 17px;

        font-weight: 500;

        line-height: 20px;

        text-transform: uppercase;
    }


    .document-title {

        font-size: 17px;

        font-weight: 500;

        line-height: 20px;

        text-transform: uppercase;
    }


    .receipt-number {

        position: absolute;

        right: 0;

        top: 1px;

        font-size: 16px;

        white-space: nowrap;
    }


    .receipt-number-value {

        color: #c62828;

        font-weight: bold;

        letter-spacing: 1px;
    }



    /* ======================================================
       DATE
    ====================================================== */

    .date-row {

        width: 100%;

        display: flex;

        justify-content: flex-end;

        align-items: flex-end;

        margin: 0 0 4px 0;
    }


    .date-label {

        font-weight: bold;

        margin-right: 5px;
    }


    .date-value {

        width: 165px;

        min-height: 16px;

        border-bottom: 1px solid #333;

        padding:

            0
            4px
            1px
            4px;

        text-align: center;

        box-sizing: border-box;
    }



    /* ======================================================
       STANDARD ROW
    ====================================================== */

    .line-row {

        display: flex;

        align-items: flex-end;

        width: 100%;

        min-height: 18px;

        margin-bottom: 2px;
    }


    .line-label {

        flex: 0 0 auto;

        margin-right: 4px;

        white-space: nowrap;
    }


    .line-value {

        flex: 1;

        min-height: 16px;

        border-bottom: 1px solid #333;

        padding:

            0
            4px
            1px
            4px;

        box-sizing: border-box;
    }


    .address-value {

        font-size: 10px;

        white-space: nowrap;

        overflow: hidden;

        text-overflow: ellipsis;
    }



    /* ======================================================
       TIN / BUSINESS STYLE
    ====================================================== */

    .split-row {

        display: flex;

        align-items: flex-end;

        width: 100%;

        min-height: 18px;

        margin-bottom: 2px;
    }


    .split-section {

        display: flex;

        align-items: flex-end;
    }


    .tin-section {

        width: 40%;

        padding-right: 8px;

        box-sizing: border-box;
    }


    .business-section {

        width: 60%;
    }


    .split-label {

        margin-right: 4px;

        white-space: nowrap;
    }


    .split-value {

        flex: 1;

        min-height: 16px;

        border-bottom: 1px solid #333;

        padding:

            0
            4px
            1px
            4px;

        box-sizing: border-box;
    }



    /* ======================================================
       AMOUNT
    ====================================================== */

    .amount-number-row {

        display: flex;

        align-items: flex-end;

        width: 100%;

        margin-bottom: 4px;
    }


    .amount-number-line {

        flex: 1;

        min-height: 17px;

        border-bottom: 1px solid #333;

        text-align: right;

        padding:

            0
            7px
            1px
            4px;

        font-size: 12px;

        font-weight: bold;

        box-sizing: border-box;
    }


    .currency-display {

        width: 70px;

        min-height: 17px;

        border-bottom: 1px solid #333;

        padding:

            0
            4px
            1px
            4px;

        font-size: 11px;

        box-sizing: border-box;
    }



    /* ======================================================
       PAYMENT BOX
    ====================================================== */

    .payment-box {

        border: 1px solid #555;

        border-radius: 8px;

        padding:

            5px
            8px
            4px
            8px;

        margin-top: 3px;

        box-sizing: border-box;
    }


    .payment-for-row {

        display: flex;

        align-items: flex-end;

        margin-bottom: 4px;
    }


    .payment-for-label {

        margin-right: 4px;

        white-space: nowrap;
    }


    .payment-for-value {

        flex: 1;

        min-height: 16px;

        border-bottom: 1px solid #333;

        padding:

            0
            4px
            1px
            4px;

        box-sizing: border-box;
    }


    .payment-details {

        display: flex;

        width: 100%;
    }


    .payment-left {

        width: 36%;

        padding-right: 10px;

        box-sizing: border-box;
    }


    .payment-right {

        width: 64%;
    }


    .payment-line {

        display: flex;

        align-items: flex-end;

        min-height: 18px;

        margin-bottom: 1px;
    }


    .payment-label {

        margin-right: 4px;

        white-space: nowrap;
    }


    .payment-value {

        flex: 1;

        min-height: 16px;

        border-bottom: 1px solid #333;

        padding:

            0
            4px
            1px
            4px;

        box-sizing: border-box;
    }


    .checkbox {

        display: inline-block;

        width: 10px;

        height: 10px;

        border: 1px solid #333;

        margin:

            0
            4px
            0
            2px;

        box-sizing: border-box;

        vertical-align: middle;
    }


    .checkbox.checked::after {

        content: "✓";

        display: block;

        font-size: 10px;

        line-height: 8px;

        text-align: center;

        font-weight: bold;
    }


    .check-row {

        display: flex;

        align-items: flex-end;

        width: 100%;

        min-height: 18px;

        margin-bottom: 1px;
    }


    .check-left {

        width: 61%;

        display: flex;

        align-items: flex-end;

        padding-right: 10px;

        box-sizing: border-box;
    }


    .check-right {

        width: 39%;

        display: flex;

        align-items: flex-end;
    }



    /* ======================================================
       FOOTER
    ====================================================== */

    .footer-row {

        display: flex;

        justify-content: space-between;

        align-items: flex-end;

        margin-top: 5px;
    }


    .tax-note {

        width: 56%;

        font-size: 9px;
    }


    .signature-section {

        width: 40%;

        text-align: center;
    }


    .signature-name {

        min-height: 16px;

        border-bottom: 1px solid #333;
    }


    .signature-label {

        font-size: 9px;

        margin-top: 1px;
    }



    /* ======================================================
       PRINT
    ====================================================== */

    @media print {

        html,
        body {

            width: 210mm !important;

            height: 105mm !important;

            margin: 0 !important;

            padding: 0 !important;
        }


        .print-format {

            width: 210mm !important;

            min-height: 105mm !important;

            margin: 0 !important;

            padding: 0 !important;
        }


        .ar-container {

            page-break-inside: avoid;

            page-break-after: avoid;
        }


        .payment-box {

            page-break-inside: avoid;
        }

    }

</style>



<div class="ar-container">


    <!-- ====================================================
         HEADER
    ===================================================== -->

    <div class="ar-header">


        <div class="company-name">

            {% if company_name
                == "OTEC International Trade Corporation" %}

                OTEC INTL TRADE CORP

            {% else %}

                {{ company_name }}

            {% endif %}

        </div>


        <div class="document-title">

            ACKNOWLEDGEMENT RECEIPT

        </div>


        <div class="receipt-number">

            <span>No.</span>

            <span class="receipt-number-value">

                {{ ar_no }}

            </span>

        </div>


    </div>



    <!-- ====================================================
         DATE
    ===================================================== -->

    <div class="date-row">


        <div class="date-label">

            DATE:

        </div>


        <div class="date-value">

            {% if receipt_date %}

                {{ frappe.utils.formatdate(
                    receipt_date,
                    "MM/dd/yyyy"
                ) }}

            {% endif %}

        </div>


    </div>



    <!-- ====================================================
         RECEIVED FROM
    ===================================================== -->

    <div class="line-row">


        <div class="line-label">

            RECEIVED FROM

        </div>


        <div class="line-value">

            {{ customer_name }}

        </div>


    </div>



    <!-- ====================================================
         ADDRESS
    ===================================================== -->

    <div class="line-row">


        <div class="line-label">

            ADDRESS

        </div>


        <div class="line-value address-value">

            {{ customer_address }}

        </div>


    </div>



    <!-- ====================================================
         TIN / BUSINESS STYLE
    ===================================================== -->

    <div class="split-row">


        <div class="split-section tin-section">


            <div class="split-label">

                TIN

            </div>


            <div class="split-value">

                {{ customer_tax_id }}

            </div>


        </div>



        <div class="split-section business-section">


            <div class="split-label">

                BUSINESS STYLE

            </div>


            <div class="split-value">

                {{ customer_industry }}

            </div>


        </div>


    </div>



    <!-- ====================================================
         AMOUNT IN WORDS
    ===================================================== -->

    <div class="line-row">


        <div class="line-label">

            THE SUM OF PESOS/UNITED STATES DOLLARS

        </div>


        <div class="line-value">

            {{ amount_words }}

        </div>


    </div>



    <!-- ====================================================
         NUMERIC AMOUNT
    ===================================================== -->

    <div class="amount-number-row">


        <div class="amount-number-line">


            {% if currency == "PHP" %}

                ₱

            {% elif currency == "USD" %}

                $

            {% else %}

                {{ currency }}

            {% endif %}


            {{ "{:,.2f}".format(receipt_amount) }}


        </div>



        <div class="currency-display">


            {% if currency == "PHP" %}

                Php

            {% elif currency == "USD" %}

                USD

            {% else %}

                {{ currency }}

            {% endif %}


        </div>


    </div>



    <!-- ====================================================
         PAYMENT BOX
    ===================================================== -->

    <div class="payment-box">


        <div class="payment-for-row">


            <div class="payment-for-label">

                As partial / full payment for

            </div>


            <div class="payment-for-value">

                {{ payment_description }}

            </div>


        </div>



        <div class="payment-details">


            <!-- CASH -->

            <div class="payment-left">


                <div class="payment-line">


                    <span class="payment-label">

                        CASH

                    </span>


                    <span class="checkbox
                        {% if is_cash %}checked{% endif %}">
                    </span>


                    <span class="payment-label">

                        AMOUNT

                    </span>


                    <div class="payment-value">


                        {% if is_cash %}


                            {% if currency == "PHP" %}

                                ₱

                            {% elif currency == "USD" %}

                                $

                            {% endif %}


                            {{ "{:,.2f}".format(
                                receipt_amount
                            ) }}


                        {% endif %}


                    </div>


                </div>


            </div>



            <!-- CHECK -->

            <div class="payment-right">


                <!-- CHECK NUMBER / AMOUNT -->

                <div class="check-row">


                    <div class="check-left">


                        <span class="payment-label">

                            CHECK

                        </span>


                        <span class="checkbox
                            {% if is_check %}checked{% endif %}">
                        </span>


                        <span class="payment-label">

                            Check No.

                        </span>


                        <div class="payment-value">


                            {% if is_check %}

                                {{ check_no }}

                            {% endif %}


                        </div>


                    </div>



                    <div class="check-right">


                        <span class="payment-label">

                            Amount

                        </span>


                        <div class="payment-value">


                            {% if is_check %}


                                {% if currency == "PHP" %}

                                    ₱

                                {% elif currency == "USD" %}

                                    $

                                {% endif %}


                                {{ "{:,.2f}".format(
                                    receipt_amount
                                ) }}


                            {% endif %}


                        </div>


                    </div>


                </div>



                <!-- BANK / BRANCH -->

                <div class="check-row">


                    <div class="check-left">


                        <span class="payment-label">

                            Bank

                        </span>


                        <div class="payment-value">


                            {% if is_check %}

                                {{ bank_name }}

                            {% endif %}


                        </div>


                    </div>



                    <div class="check-right">


                        <span class="payment-label">

                            Branch

                        </span>


                        <div class="payment-value">


                            {% if is_check %}

                                {{ bank_branch }}

                            {% endif %}


                        </div>


                    </div>


                </div>



                <!-- CHECK DATE -->

                <div class="payment-line">


                    <span class="payment-label">

                        Check Date:

                    </span>


                    <div class="payment-value">


                        {% if is_check and check_date %}


                            {{ frappe.utils.formatdate(
                                check_date,
                                "MM/dd/yyyy"
                            ) }}


                        {% endif %}


                    </div>


                </div>


            </div>


        </div>


    </div>



    <!-- ====================================================
         FOOTER
    ===================================================== -->

    <div class="footer-row">


        <div class="tax-note">

            "This document is not valid for claim of Input Tax"

        </div>


        <div class="signature-section">


            <div class="signature-name">

                &nbsp;

            </div>


            <div class="signature-label">

                Cashier / Authorized Representative

            </div>


        </div>


    </div>


</div>
